package cn.blockforge.generated.generatedmod.divinesurvey.client;
import cn.blockforge.generated.generatedmod.GeneratedMod;import cn.blockforge.generated.generatedmod.divinesurvey.SurveyPacket;
import com.mojang.blaze3d.platform.InputConstants;import net.minecraft.client.*;import net.minecraft.client.gui.Font;import net.minecraft.client.renderer.*;import net.minecraft.world.phys.*;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.client.event.*;import net.minecraftforge.client.gui.overlay.VanillaGuiOverlay;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import org.lwjgl.glfw.GLFW;import java.util.*;
public final class SurveyClient {
 private static final List<SurveyPacket.Target> ores=new ArrayList<>();private static final ArrayDeque<SurveyPacket.Target> waypoints=new ArrayDeque<>();private static final Set<String> knownStructures=new HashSet<>();private static List<SurveyPacket.Target> nearby=new ArrayList<>();private static boolean active;private static String dimension="";private static int completed;
 public static boolean active(){return active;}
 public static void accept(SurveyPacket p){var mc=Minecraft.getInstance();if(mc.level==null||!mc.level.dimension().location().toString().equals(p.dimension()))return;dimension=p.dimension();completed=p.completed();if(p.mode()==0||p.mode()==1){ores.clear();nearby.clear();waypoints.clear();active=p.mode()==1;return;}if(!active)return;for(var t:p.targets()){if(t.kind()==1){String key=dimension+":"+t.name()+":"+t.x()+":"+t.z();if(SurveyClientConfig.XAERO_WAYPOINTS.get()&&knownStructures.add(key))waypoints.add(t);ores.add(new SurveyPacket.Target(t.x(),t.y(),t.z(),t.ex(),t.ey(),t.ez(),"结构 · "+StructureNames.display(t.name()),t.color(),1));}else{String[] name=t.name().split("\\|",2);String label=net.minecraft.network.chat.Component.translatable(name[0]).getString()+(name.length>1?" ×"+name[1]:"");ores.add(new SurveyPacket.Target(t.x(),t.y(),t.z(),t.ex(),t.ey(),t.ez(),label,t.color(),0));}}}
 @Mod.EventBusSubscriber(modid=GeneratedMod.MOD_ID,value=Dist.CLIENT,bus=Mod.EventBusSubscriber.Bus.FORGE) public static class Events {
  @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.level==null||!dimension.equals(mc.level.dimension().location().toString())){active=false;ores.clear();waypoints.clear();knownStructures.clear();nearby.clear();}if(active&&mc.player!=null&&mc.player.tickCount%10==0){var at=mc.player.position();Comparator<SurveyPacket.Target> distance=Comparator.comparingDouble(t->at.distanceToSqr(new Vec3((t.x()+t.ex())/2,(t.y()+t.ey())/2,(t.z()+t.ez())/2)));PriorityQueue<SurveyPacket.Target> nearest=new PriorityQueue<>(2048,distance.reversed());for(var target:ores){if(nearest.size()<2048)nearest.add(target);else if(distance.compare(target,nearest.peek())<0){nearest.poll();nearest.add(target);}}nearby=new ArrayList<>(nearest);nearby.sort(distance);}if(!SurveyClientConfig.XAERO_WAYPOINTS.get())waypoints.clear();if(active&&mc.player!=null&&mc.player.tickCount%40==0&&!waypoints.isEmpty()){var w=waypoints.peek();if(XaeroSurveyCompat.add(w))waypoints.poll();}}
  @SubscribeEvent public static void hud(RenderGuiOverlayEvent.Post e){var mc=Minecraft.getInstance();if(!active||mc.options.hideGui||!e.getOverlay().id().equals(VanillaGuiOverlay.HOTBAR.id()))return;e.getGuiGraphics().drawString(mc.font,"神识外放 · "+completed+"/64 区块 · 矿簇 "+ores.size()+" · 识海页收回",8,mc.getWindow().getGuiScaledHeight()-95,0xFFEACD83,true);}
  @SubscribeEvent public static void render(RenderLevelStageEvent e){if(!active||e.getStage()!=RenderLevelStageEvent.Stage.AFTER_PARTICLES)return;var mc=Minecraft.getInstance();if(mc.level==null||mc.options.hideGui)return;try(var state=new SurveyRenderState()){var camera=e.getCamera();var origin=camera.getPosition();var pose=new com.mojang.blaze3d.vertex.PoseStack();pose.last().pose().set(e.getPoseStack().last().pose());pose.last().normal().set(e.getPoseStack().last().normal());var buffers=mc.renderBuffers().bufferSource();List<SurveyPacket.Target> all=nearby;int rendered=0;
   pose.last().pose().set(SurveyTransform.worldView(pose.last().pose(),origin.x,origin.y,origin.z));pose.pushPose();var lines=buffers.getBuffer(SurveyLines.THROUGH);for(var t:all){AABB b=new AABB(t.x(),t.y(),t.z(),t.ex(),t.ey(),t.ez());if(!e.getFrustum().isVisible(b))continue;if(rendered++>=512)break;float red=((t.color()>>16)&255)/255F,green=((t.color()>>8)&255)/255F,blue=(t.color()&255)/255F;LevelRenderer.renderLineBox(pose,lines,b,red,green,blue,1);}
   buffers.endBatch(SurveyLines.THROUGH);pose.popPose();int labels=0;for(var t:all){var center=new Vec3((t.x()+t.ex())/2,(t.y()+t.ey())/2,(t.z()+t.ez())/2);if(!e.getFrustum().isVisible(new AABB(t.x(),t.y(),t.z(),t.ex(),t.ey(),t.ez())))continue;if(labels++>=64)break;pose.pushPose();pose.translate(center.x,center.y,center.z);pose.mulPose(camera.rotation());float scale=(float)Math.max(.025,Math.min(.18,center.distanceTo(origin)*.0015));pose.scale(-scale,-scale,scale);mc.font.drawInBatch(t.name(),-mc.font.width(t.name())/2F,0,t.color(),false,pose.last().pose(),buffers,Font.DisplayMode.SEE_THROUGH,0x88000000,15728880);pose.popPose();}com.mojang.blaze3d.systems.RenderSystem.disableDepthTest();com.mojang.blaze3d.systems.RenderSystem.depthMask(false);buffers.endBatch();com.mojang.blaze3d.systems.RenderSystem.depthMask(true);com.mojang.blaze3d.systems.RenderSystem.enableDepthTest();}
  }
 }
}
